import{_ as t,o as r,c as e,a2 as i}from"./chunks/framework.BW2T23B9.js";const g=JSON.parse('{"title":"什么是 Turna？","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-turna.md","filePath":"guide/what-is-turna.md","lastUpdated":1787830168000}'),l={name:"guide/what-is-turna.md"};function n(o,a,s,u,d,h){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="什么是-turna" tabindex="-1">什么是 Turna？ <a class="header-anchor" href="#什么是-turna" aria-label="Permalink to &quot;什么是 Turna？&quot;">​</a></h1><p>Turna（土耳其语中意为「鹤」）是一款<strong>本地优先、离线可用</strong>的开源语言学习应用，目前专注土耳其语。</p><h2 id="解决的问题" tabindex="-1">解决的问题 <a class="header-anchor" href="#解决的问题" aria-label="Permalink to &quot;解决的问题&quot;">​</a></h2><p>很多语言学习工具强依赖云端：没网就停摆、课程固定不能改、复习节奏全靠服务器决定。Turna 走的是相反的路：</p><ul><li><strong>离线能用</strong>：课程数据存在本地，无网络时照常学习与复习。</li><li><strong>节奏可调</strong>：内置开源 FSRS 算法，按你的真实记忆曲线安排复习。</li><li><strong>课程可改</strong>：桌面端提供课程编辑器，课时蓝图与内容可双向编辑。</li><li><strong>不锁数据</strong>：复用官方 Anki 内核，牌组可导入导出。</li></ul><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li>想系统学习土耳其语、但不想被网络与订阅绑住的人。</li><li>已经在用 Anki 复习、希望牌组「课程化」、按课时推进的人。</li><li>喜欢研究记忆算法、对 FSRS 的工程实现感兴趣的人。</li><li>想二次开发或自部署语言学习工具的开发者。</li></ul><h2 id="当前阶段" tabindex="-1">当前阶段 <a class="header-anchor" href="#当前阶段" aria-label="Permalink to &quot;当前阶段&quot;">​</a></h2><p>Turna 是<strong>持续开发中的开源项目</strong>，课程内容还在缓慢扩充中。功能上，「离线学习 + FSRS 复习 + Anki 导入 + AI 伴学 + 课程编辑器」已经可用。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/guide/getting-started">5 分钟本地跑起来</a></li><li><a href="/docs/guide/features">核心能力一览</a></li><li><a href="/docs/guide/curriculum">课程结构</a></li></ul>',11)])])}const _=t(l,[["render",n]]);export{g as __pageData,_ as default};
